-- 20260723212044_create_prediction_components.sql
-- RECONSTRUCTED 2026-07-30 from live schema introspection — no file existed
-- for this previously-applied version in either local migration tree.
-- id column confirmed via information_schema to use a sequence default
-- (nextval('prediction_components_id_seq'::regclass)) — reconstructed as
-- GENERATED BY DEFAULT AS IDENTITY, functionally equivalent.
--
-- Also fixes a real gap found in the same diagnosis: RLS was never enabled
-- on this table (created after 20260719142239's blanket enable, so it never
-- got it) — this reconstruction includes it going forward.

CREATE TABLE IF NOT EXISTS prediction_components (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    prediction_id BIGINT,
    symbol VARCHAR,
    component_name VARCHAR,
    raw_score NUMERIC,
    weight NUMERIC,
    contribution NUMERIC,
    source VARCHAR,
    ingested_at TIMESTAMPTZ
);

ALTER TABLE prediction_components ENABLE ROW LEVEL SECURITY;
